import{_ as t,a as d,c as r,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Redis Sorted Set（有序集合） · 旧版兼容命令至6. 过期、持久化与生命周期","description":"排行榜、在线状态、匹配与延迟任务，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis Sorted Set（有序集合） · 旧版兼容命令至6. 过期、持久化与生命周期","description":"排行榜、在线状态、匹配与延迟任务，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/sorted-set.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis Sorted Set（有序集合）","summary":"排行榜、在线状态、匹配与延迟任务，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis Sorted Set（有序集合） · 1. 定位：解决什么问题至2. 命令速查与示例","link":"/middleware/redis/plus/subjects/sorted-set-part-01"},"next":{"text":"Redis Sorted Set（有序集合） · 7. 集群与扩展至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/sorted-set-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis Sorted Set（有序集合） · 1. 定位：解决什么问题至2. 命令速查与示例","link":"/middleware/redis/plus/subjects/sorted-set-part-01"},"next":{"text":"Redis Sorted Set（有序集合） · 7. 集群与扩展至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/sorted-set-part-03"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/sorted-set-part-02.md","filePath":"middleware/redis/plus/subjects/sorted-set-part-02.md"}'),a={name:"middleware/redis/plus/subjects/sorted-set-part-02.md"};function i(l,e,o,c,n,p){return d(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="redis-sorted-set-有序集合-·-旧版兼容命令至6-过期、持久化与生命周期" tabindex="-1">Redis Sorted Set（有序集合） · 旧版兼容命令至6. 过期、持久化与生命周期 <a class="header-anchor" href="#redis-sorted-set-有序集合-·-旧版兼容命令至6-过期、持久化与生命周期" aria-label="Permalink to &quot;Redis Sorted Set（有序集合） · 旧版兼容命令至6. 过期、持久化与生命周期&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/sorted-set">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="旧版兼容命令" tabindex="-1">旧版兼容命令 <a class="header-anchor" href="#旧版兼容命令" aria-label="Permalink to &quot;旧版兼容命令 {#旧版兼容命令}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-zrangebyscore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrangebyscore.json" target="_blank" rel="noopener noreferrer">ZRANGEBYSCORE</a><br>旧式分数区间查询</td><td><code>ZRANGEBYSCORE learn:{zset}:a 10 20 WITHSCORES</code><br>新代码用 ZRANGE ... BYSCORE。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zrevrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrevrange.json" target="_blank" rel="noopener noreferrer">ZREVRANGE</a><br>旧式倒序名次查询</td><td><code>ZREVRANGE learn:{zset}:a 0 1 WITHSCORES</code><br>返回 carol、bob；新代码用 ZRANGE ... REV。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zrevrangebyscore"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrevrangebyscore.json" target="_blank" rel="noopener noreferrer">ZREVRANGEBYSCORE</a><br>旧式倒序分数查询</td><td><code>ZREVRANGEBYSCORE learn:{zset}:a 30 20 WITHSCORES</code><br>上界在前；新代码用 ZRANGE ... BYSCORE REV。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zrangebylex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrangebylex.json" target="_blank" rel="noopener noreferrer">ZRANGEBYLEX</a><br>旧式字典序查询</td><td><code>ZRANGEBYLEX learn:{zset}:lex [a [b</code><br>同分集合返回 a、b；新代码用 ZRANGE ... BYLEX。</td><td>O(log N+M)</td></tr><tr><td><span id="cmd-zrevrangebylex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/zrevrangebylex.json" target="_blank" rel="noopener noreferrer">ZREVRANGEBYLEX</a><br>旧式倒序字典序查询</td><td><code>ZREVRANGEBYLEX learn:{zset}:lex [c [b</code><br>返回 c、b；新代码用 ZRANGE ... BYLEX REV。</td><td>O(log N+M)</td></tr></tbody></table><details class="details custom-block"><summary>版本与复杂度补充</summary><p>下表保留每条命令的引入版本、兼容状态及复杂度符号含义；复杂度不包含全部网络传输、内存分配和等待成本。</p><table tabindex="0"><thead><tr><th>命令</th><th>引入版本与状态</th><th>复杂度说明</th></tr></thead><tbody><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zadd">ZADD</a></td><td>1.2.0</td><td>每个成员 O(log N)，N 为目标集合大小；多成员累加。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zincrby">ZINCRBY</a></td><td>1.2.0</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zscore">ZSCORE</a></td><td>1.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zmscore">ZMSCORE</a></td><td>6.2.0</td><td>O(M)，M 为指定或返回成员数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zcard">ZCARD</a></td><td>1.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zrandmember">ZRANDMEMBER</a></td><td>6.2.0</td><td>O(M)，M 为指定或返回成员数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zscan">ZSCAN</a></td><td>2.8.0</td><td>官方渐进遍历口径：单次 O(1)，完整迭代 O(N)；COUNT 只是提示，编码和结果数量影响耗时。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zcount">ZCOUNT</a></td><td>2.0.0</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zlexcount">ZLEXCOUNT</a></td><td>2.8.9</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zrank">ZRANK</a></td><td>2.0.0</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zrevrank">ZREVRANK</a></td><td>2.0.0</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zrange">ZRANGE</a></td><td>1.2.0</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zrangestore">ZRANGESTORE</a></td><td>6.2.0</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zrem">ZREM</a></td><td>1.2.0</td><td>O(M log N)，N 为集合大小，M 为指定删除或弹出的成员数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zremrangebyrank">ZREMRANGEBYRANK</a></td><td>2.0.0</td><td>O(log N+M)，M 为实际移除数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zremrangebyscore">ZREMRANGEBYSCORE</a></td><td>1.2.0</td><td>O(log N+M)，M 为实际移除数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zremrangebylex">ZREMRANGEBYLEX</a></td><td>2.8.9</td><td>O(log N+M)，M 为实际移除数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zpopmin">ZPOPMIN</a></td><td>5.0.0</td><td>O(M log N)，N 为集合大小，M 为指定删除或弹出的成员数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zpopmax">ZPOPMAX</a></td><td>5.0.0</td><td>O(M log N)，N 为集合大小，M 为指定删除或弹出的成员数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zmpop">ZMPOP</a></td><td>7.0.0</td><td>O(K+M log N)，K 为提供的键数，N 为选中集合大小，M 为弹出数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-bzpopmin">BZPOPMIN</a></td><td>5.0.0</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-bzpopmax">BZPOPMAX</a></td><td>5.0.0</td><td>O(log N)，N 为集合大小；阻塞等待时间另计。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-bzmpop">BZMPOP</a></td><td>7.0.0</td><td>O(K+M log N)，K 为提供的键数，N 为选中集合大小，M 为弹出数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zinter">ZINTER</a></td><td>6.2.0</td><td>最坏 O(Nmin×K+M log M)，Nmin 为最小输入集合大小，K 为集合数，M 为结果大小。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zintercard">ZINTERCARD</a></td><td>7.0.0</td><td>最坏 O(Nmin×K)，Nmin 为最小集合大小，K 为集合数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zinterstore">ZINTERSTORE</a></td><td>2.0.0</td><td>最坏 O(Nmin×K+M log M)，Nmin 为最小输入集合大小，K 为集合数，M 为结果大小。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zunion">ZUNION</a></td><td>6.2.0</td><td>O(T+M log M)，T 为输入成员总数，M 为结果大小。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zunionstore">ZUNIONSTORE</a></td><td>2.0.0</td><td>O(T+M log M)，T 为输入成员总数，M 为结果大小。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zdiff">ZDIFF</a></td><td>6.2.0</td><td>最坏 O(T+(N−M) log N)，T 为输入成员总数，N 为第一个集合大小，M 为结果大小。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-01#cmd-zdiffstore">ZDIFFSTORE</a></td><td>6.2.0</td><td>最坏 O(T+(N−M) log N)，T 为输入成员总数，N 为第一个集合大小，M 为结果大小。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-02#cmd-zrangebyscore">ZRANGEBYSCORE</a></td><td>1.0.5；从 6.2.0 起弃用（兼容保留）</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-02#cmd-zrevrange">ZREVRANGE</a></td><td>1.2.0；从 6.2.0 起弃用（兼容保留）</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-02#cmd-zrevrangebyscore">ZREVRANGEBYSCORE</a></td><td>2.2.0；从 6.2.0 起弃用（兼容保留）</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-02#cmd-zrangebylex">ZRANGEBYLEX</a></td><td>2.8.9；从 6.2.0 起弃用（兼容保留）</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/sorted-set-part-02#cmd-zrevrangebylex">ZREVRANGEBYLEX</a></td><td>2.8.9；从 6.2.0 起弃用（兼容保留）</td><td>O(log N+M)，N 为源集合大小，M 为返回或保存数；大 LIMIT 偏移还增加扫描成本。</td></tr></tbody></table></details><p>ZRANGE 默认按排名，没有 BYRANK；BYSCORE、BYLEX、REV、LIMIT 从 6.2 起支持。BYLEX 系列示例使用同分成员，不能把不同分数集合当成全局字典序索引。</p><p>通用键操作见<a href="/middleware/redis/base/basic/keys">键与过期时间</a>，这里集中列出类型自身的命令。</p><h2 id="encoding" tabindex="-1">3. 底层编码与内存 <a class="header-anchor" href="#encoding" aria-label="Permalink to &quot;3. 底层编码与内存 {#encoding}&quot;">​</a></h2><p>小 ZSet 使用 <code>listpack</code>，超出条件后使用 <code>skiplist</code> 编码，对应跳表加字典：跳表支持排序和范围查询，字典支持成员定位。因此底层表示的查找成本也要区分操作。</p><p>8.2.10 默认 <code>zset-max-listpack-entries 128</code>、<code>zset-max-listpack-value 64</code>（成员字节长度）。超过任一条件可触发转换；不要把 128 当成集合最大容量，也不要假设删除成员后一定恢复紧凑编码。</p><h3 id="编码与内存怎么测" tabindex="-1">编码与内存怎么测 <a class="header-anchor" href="#编码与内存怎么测" aria-label="Permalink to &quot;编码与内存怎么测 {#编码与内存怎么测}&quot;">​</a></h3><p>在独立实验实例准备教学键，再读实际状态；下列是测量方法，本次未运行或填写测量数字：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZADD learn:types:rank 10 alice 20 bob</span></span>
<span class="line"><span>OBJECT ENCODING learn:types:rank</span></span>
<span class="line"><span>MEMORY USAGE learn:types:rank</span></span></code></pre></div><p>固定键名、元素字节长度、Redis 版本和分配器，分别记录 1、10、100 个元素或不同值长度时的内存，再跨越编码阈值观察。单元素的增量开销可用相邻两次内存差估计，编码转换时不能套用线性平均；String/Bitmap 的横轴应使用字节数或最高位偏移。比较“一键多元素”和“多个独立键”时，把键名、对象、字典项和 TTL 管理开销一起计入。</p><p>MEMORY USAGE 默认对嵌套值采样，<code>SAMPLES 0</code> 会遍历所有嵌套值，仅在小型隔离实验中使用。其结果不等同于进程 RSS；大量键还会增加全局字典、分配器碎片和复制缓冲等成本，需结合 INFO memory。没有适用于所有版本的固定“每 key 几字节”。</p><p>依据：<a href="https://github.com/redis/redis/blob/8.2.10/redis.conf" target="_blank" rel="noopener noreferrer">8.2.10 配置</a>、<a href="https://github.com/redis/redis/blob/8.2.10/src/t_zset.c" target="_blank" rel="noopener noreferrer">对应类型实现</a>、<a href="https://redis.io/docs/latest/commands/memory-usage/" target="_blank" rel="noopener noreferrer">MEMORY USAGE</a>。</p><h2 id="performance" tabindex="-1">4. 性能与阻塞风险 <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;4. 性能与阻塞风险 {#performance}&quot;">​</a></h2><p>ZSCORE 是 O(1)，ZINCRBY/排名查询是 O(log N)，大范围查询和批量清理会随结果规模增长。ZRANGE LIMIT 大偏移可能需要走过许多成员，不能只看最终返回 10 条。ZSCAN 可用于无序维护，但不提供名次顺序或快照。热点榜单需限制请求范围与清理批次。</p><p>常规命令执行主要占用主执行路径，耗时计算会拖慢同实例其他请求；网络 I/O、后台持久化和释放内存有其他线程/进程参与。命令复杂度不包含所有网络、分配、编码转换与客户端成本。</p><h2 id="atomicity" tabindex="-1">5. 原子性与并发 <a class="header-anchor" href="#atomicity" aria-label="Permalink to &quot;5. 原子性与并发 {#atomicity}&quot;">​</a></h2><p>ZINCRBY 原子增加分数；先查排名、再按结果修改涉及两次命令，需要 Lua 或 WATCH。匹配时“按分数取候选、校验、移除”应在同一脚本中完成，ZPOPMIN 不能替代任意分数区间匹配。原子领取延迟任务仍需要处理中租约和业务幂等来应对消费者崩溃。</p><p>MULTI/EXEC 保证排队命令连续执行，但执行时单条报错不会回滚其他已成功命令；WATCH 是乐观冲突检测，需要有界重试。Lua 也不会自动回滚运行错误前的写入，应先校验参数与类型，再修改状态。</p><h2 id="lifecycle" tabindex="-1">6. 过期、持久化与生命周期 <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;6. 过期、持久化与生命周期 {#lifecycle}&quot;">​</a></h2><p>只有整键 TTL，没有成员 TTL。滑动窗口与在线心跳需显式删除过旧 score；ZRANGE 是查询，不会自动清理。按赛季或业务日分键后设置保留期。大范围 ZREMRANGEBYSCORE 也会占用执行时间，应结合批量策略或按时间分桶。</p><p>大键会增加 RDB/AOF 重写、复制全量同步和恢复时的处理量，fork 写时复制还可能增加峰值内存。单次同步删除聚合对象可能阻塞；<code>UNLINK</code> 先摘除键，把主要回收工作移到后台，但总回收工作和内存压力仍存在，不能替代限长和拆分。</p><p>完成教学实验后，只清理自己创建的键，例如 <code>UNLINK learn:types:rank</code>。</p>`,27)])])}const b=t(a,[["render",i]]);export{u as __pageData,b as default};
